mapper.select:
select t1.id, t1.image_name, t1.image, t1.province,t1.city, t1.leftdown_longitude, t1.leftdown_latitude, t1.rightup_longitude,
t1.rightup_latitude,t1.collect_time, t1.region, t1.satellite_id,
t1.start_time, t1.end_time, t1.satellite_type, t1.sensor_type, t1.user_id, t1.create_by, t1.create_time, t1.update_by,
t1.update_time, t1.view_path, t1.view_row, t1.star_path, t1.star_row, t1.leftup_longitude, t1.leftup_latitude,
t1.rightdown_longitude,t1.rightdown_latitude, t2.dict_label as satelliteName
from record_info t1
left join sys_dict_data t2 on t1.satellite_type = t2.dict_code


        and image_name like concat('%', #{imageName}, '%')


        and image = #{image}


        and province = #{province}


        and city = #{city}


        and leftdown_longitude = #{leftdownLongitude}


        and leftdown_latitude = #{leftdownLatitude}


        and rightup_longitude = #{rightupLongitude}


        and rightup_latitude = #{rightupLatitude}


        and `start_time` between #{params.beginStartTime} and #{params.endStartTime}


        and end_time = #{endTime}


        and satellite_type = #{satelliteType}


        and sensor_type = #{sensorType}


        and user_id = #{userId}


        and view_path = #{viewPath}


        and view_row = #{viewRow}


        and star_path = #{starPath}


        and star_row = #{starRow}


        and leftup_longitude = #{leftupLongitude}


        and leftup_latitude = #{leftupLatitude}


        and rightdown_longitude = #{rightdownLongitude}


        and rightdown_latitude = #{rightdownLatitude}


        and collect_time = #{collectTime}


        and region = #{region}


ORDER BY create_time desc
